use mdbook_language_lab::process;
use serde_json::{Value, json};

fn chapter(path: &str, content: &str) -> Value {
    json!({"Chapter": {"path": path, "content": content, "sub_items": []}})
}
fn render(source: &str) -> String {
    let mut book = json!({"items": [chapter("test.md", source)]});
    process(&mut book).unwrap();
    book["items"][0]["Chapter"]["content"]
        .as_str()
        .unwrap()
        .into()
}

fn href(from: &str, to: &str, id: &str) -> String {
    if from == to {
        return format!("#req-{id}");
    }
    let from: Vec<_> = from.split('/').collect();
    let target = Path::new(to)
        .with_extension("html")
        .to_string_lossy()
        .replace('\\', "/");
    let to: Vec<_> = target.split('/').collect();
    let common = from[..from.len() - 1]
        .iter()
        .zip(&to)
        .take_while(|(a, b)| a == b)
        .count();
    let path = format!(
        "{}{}",
        "../".repeat(from.len() - 1 - common),
        to[common..].join("/")
    );
    let encoded: String = path
        .bytes()
        .map(|b| {
            if b.is_ascii_alphanumeric() || b"/-._~".contains(&b) {
                (b as char).to_string()
            } else {
                format!("%{b:02X}")
            }
        })
        .collect();
    format!("{encoded}#req-{id}")
}

chapters(items, &mut |ch| {
    let source = ch["content"].as_str().ok_or("missing chapter content")?;
    let mut output = source.to_owned();
    for role in roles(source).into_iter().rev() {
        let path = ch["path"]
            .as_str()
            .ok_or("role in chapter without output path")?;
        let definition = role.name == "req";
        let id = if definition { &role.label } else { &role.name };
        let target = definitions
            .get(id)
            .ok_or_else(|| format!("{path}: unknown requirement {id}"))?;
        let html = if definition {
            format!(
                "<a class=\"requirement-badge\" id=\"req-{id}\" href=\"#req-{id}\" aria-label=\"Requirement {id}\"><span class=\"requirement-kind\">REQ</span><span class=\"requirement-name\">{id}</span></a>"
            )
        } else {
            format!(
                "<a class=\"requirement-reference\" href=\"{}\" title=\"Requirement {id}\">{}</a>",
                escape(&href(path, target, id)),
                escape(&role.label)
            )
        };
        output.replace_range(role.range, &html);
    }
    ch["content"] = output.into();
    Ok(())

#[test]
fn references_resolve_before_and_after_nested_definitions() {
    for reversed in [false, true] {
        let source = chapter("guide/deep/start.md", "{a.b}`Go there`");
        let mut parent = chapter("design/root.md", "Parent");
        parent["Chapter"]["sub_items"] = json!([chapter("design/Greek α.md", "{req}`a.b` Rule.")]);
        let items = if reversed {
            vec![parent, source]
        } else {
            vec![source, parent]
        };
        let mut book = json!({"items":items});
        process(&mut book).unwrap();
        let index = usize::from(reversed);
        assert_eq!(
            book["items"][index]["Chapter"]["content"],
            "<a class=\"requirement-reference\" href=\"../../design/Greek%20%CE%B1.html#req-a.b\" title=\"Requirement a.b\">Go there</a>"
        );
    }
    let local = render("{req}`a.b` Rule.\n\n{a.b}`local`");
    assert!(local.contains("href=\"#req-a.b\" title=\"Requirement a.b\">local</a>"));
}
